,"isLinked":false},"reverse_order_mobile":"reverse-mobile","element_pack_agbg_color_list":[{"_id":"670e0ba"},{"start_color":"#567445","end_color":"#1D1BE0","_id":"791c1e0"}]},"elements":[{"id":"56e1319","elType":"column","settings":{"_column_size":50,"_inline_size":null,"content_position":"center","space_between_widgets":10},"elements":[{"id":"16ca2b6","elType":"widget","settings":{"title":"Meet Dr. Roth Lewis","title_color":"#FFFFFF","typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":40,"sizes":[]},"typography_font_weight":"400","_padding":{"unit":"px","top":"0","right":"0","bottom":"10","left":"0","isLinked":false},"element_pack_widget_tooltip_text":"This is Tooltip","element_pack_widget_effect_transition_duration":"300","element_pack_widget_effect_transition_easing":"ease-out"},"elements":[],"widgetType":"heading"},{"id":"b2d17f6","elType":"widget","settings":{"editor":"<p><b><span data-contrast="auto">Dr.</span></b><b><span data-contrast="auto"> Roth Rube Harrison Lewis</span></b><span data-contrast="auto"> </span><span data-contrast="auto">is a proud native of the area. Dr. Lewis was raised on a local dairy farm in Ashford, AL. </span><span data-contrast="auto">W</span><span data-contrast="auto">here he learned</span><span data-contrast="auto"> the value of education, hard work, dedication, </span><span data-contrast="auto">discipline</span><span data-contrast="auto">, and Christian family values.</span><span data-ccp-props="{"> </span></p><p><span data-contrast="auto">Dr. Lewis </span><span data-contrast="auto">earned his </span><span data-contrast="auto">D</span><b><span data-contrast="auto">octorate in </span></b><b><span data-contrast="auto">D</span></b><b><span data-contrast="auto">ental </span></b><b><span data-contrast="auto">M</span></b><b><span data-contrast="auto">edicine</span></b><span data-contrast="auto"> from the prestigious </span><b><span data-contrast="auto">University of Louisville School of Dentistry</span></b><span data-contrast="auto"> </span><span data-contrast="auto">(Louisville, KY) </span><span data-contrast="auto">in 2</span><span data-contrast="auto">016</span><span data-contrast="auto">. While attending the University, Dr. </span><span data-contrast="auto">Lewis</span><span data-contrast="auto"> was named a</span><span data-contrast="auto"> </span><b><span data-contrast="auto">Deans Scholar</span></b><b><span data-contrast="auto"> </span></b><span data-contrast="auto">for his high levels of academic and clinical achievements.</span><span data-ccp-props="{"> </span></p><p><span data-contrast="auto">Prior to attending the University of Louisville, Dr. </span><span data-contrast="auto">Lewis went to </span><b><span data-contrast="auto">University of Alabama at Birmingham, UAB</span></b><span data-contrast="auto"> (</span><span data-contrast="auto">Birmingham, AL</span><span data-contrast="auto">)</span><span data-contrast="auto"> for his undergrad and</span><span data-contrast="auto"> received </span><span data-contrast="auto">a </span><span data-contrast="auto">Bachelor's of Art in Spanish</span><span data-contrast="auto"> </span><span data-contrast="auto">graduating Magna Sum Laude.</span><span data-ccp-props="{"> </span></p><p><span data-contrast="auto">With a commitment to delivering the highest level of contemporary, comprehensive and compassionate dental care, </span><b><span data-contrast="auto">Dr. </span></b><b><span data-contrast="auto">Lewis</span></b><b><span data-contrast="auto"> established his own practice in </span></b><b><span data-contrast="auto">Dothan</span></b><b><span data-contrast="auto"> in 20</span></b><b><span data-contrast="auto">20</span></b><span data-contrast="auto">. Dedicated to staying current and proficient with leading edge dentistry, he has incorporated some of the most advanced dental technology and techniques into his practice, and participates regularly in continuing education and advanced training courses throughout the country</span><span data-contrast="auto"> to better the lives of his patients.</span><span data-ccp-props="{"> </span></p><p><span data-contrast="auto">His passion and dedication in dentistry has been recognized both locally and nationally. </span><span data-ccp-props="{"> </span></p><p><span data-contrast="auto">Dr. </span><span data-contrast="auto">Lewis</span><span data-contrast="auto">’</span><span data-contrast="auto"> membership</span><span data-contrast="auto">s</span><span data-contrast="auto"> have included:</span><span data-ccp-props="{"> </span></p><ul><li data-leveltext="" data-font="Symbol" data-listid="1" aria-setsize="-1" data-aria-posinset="1" data-aria-level="1"><strong>American Dental Association </strong></li><li data-leveltext="" data-font="Symbol" data-listid="1" aria-setsize="-1" data-aria-posinset="2" data-aria-level="1"><strong>American Academy of Dental Sleep Medicine</strong></li><li data-leveltext="" data-font="Symbol" data-listid="1" aria-setsize="-1" data-aria-posinset="2" data-aria-level="1"><strong>Alabama Dental Association</strong></li><li data-leveltext="" data-font="Symbol" data-listid="1" aria-setsize="-1" data-aria-posinset="2" data-aria-level="1"><strong>Academy of General Dentistry </strong></li><li data-leveltext="" data-font="Symbol" data-listid="1" aria-setsize="-1" data-aria-posinset="2" data-aria-level="1"><strong>Kentucky Dental Association </strong></li><li data-leveltext="" data-font="Symbol" data-listid="1" aria-setsize="-1" data-aria-posinset="2" data-aria-level="1"><strong>American Academy of Cosmetic Dentistry </strong></li></ul>","align_mobile":"center","text_color":"#FFFFFF","typography_typography":"custom","typography_font_family":"Roboto","typography_font_size":{"unit":"px","size":16,"sizes":[]},"typography_font_weight":"300","typography_line_height":{"unit":"px","size":30,"sizes":[]},"element_pack_widget_tooltip_text":"This is Tooltip","element_pack_widget_effect_transition_durat