},"elements":[{"id":"52b1654","elType":"widget","settings":{"title":"Why Choose Us?","align_mobile":"center","title_color":"#283460","typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":46,"sizes":[]},"typography_font_size_mobile":{"unit":"px","size":31,"sizes":[]},"typography_font_weight":"400","typography_line_height":{"unit":"px","size":58,"sizes":[]},"_padding_mobile":{"unit":"px","top":"20","right":"0","bottom":"0","left":"0","isLinked":false}},"elements":[],"widgetType":"heading"},{"id":"8dc3645","elType":"widget","settings":{"editor":"<p>“While a large part of what we do at Southeast Dental is aesthetic and very complex treatment driven, the core of what we do is general family care.”</p>","align_mobile":"center","text_color":"#4F4F4F","typography_typography":"custom","typography_font_family":"Roboto","typography_font_size":{"unit":"px","size":16,"sizes":[]},"typography_font_weight":"500","typography_line_height":{"unit":"px","size":30,"sizes":[]}},"elements":[],"widgetType":"text-editor"},{"id":"dcdbd32","elType":"widget","settings":{"editor":"<p><span data-contrast="auto">Thank you for visiting the website o</span><span data-contrast="auto">f <strong>Southeast Dental</strong></span><span data-contrast="auto">. Our website provides important information that will help you become familiar with our practice. It also contains answers to frequently asked questions. </span></p><p><b><span data-contrast="auto">Please feel free to call us anytime</span></b><b><span data-contrast="auto">: </span></b><b><span data-contrast="auto"><a href="tel:(334)370-9055">(334) 370-9055</a> or (334) 3-DENTAL</span></b><span data-contrast="auto">.</span><span data-contrast="auto"> We appreciate this opportunity to introduce ourselves and  </span><b><span data-contrast="auto">look forward to providing you with quality dental care</span></b><span data-contrast="auto">.</span><span data-ccp-props="{"> </span></p><p><span data-contrast="auto">We want you to know that in our office </span><b><span data-contrast="auto">you can expect to be treated with respect at all times</span></b><span data-contrast="auto">. We strive to deliver </span><b><span data-contrast="auto">the best diagnosis and treatment that dentistry has to offer.</span></b><span data-contrast="auto"> We believe that these goals can be met through a continuous and open dialogue between you and our entire team.</span><span data-ccp-props="{"> </span></p><p><span data-contrast="auto">We encourage you to involve yourself in your own treatment and ask questions throughout our relationship. In our opinion, an informed and involved patient is most likely to achieve the highest level of healthcare, and look forward to working with you to achieve this goal.</span><span data-ccp-props="{"> </span></p>","align_mobile":"center","text_color":"#4F4F4F","typography_typography":"custom","typography_font_family":"Roboto","typography_font_size":{"unit":"px","size":16,"sizes":[]},"typography_font_weight":"300","typography_line_height":{"unit":"px","size":30,"sizes":[]}},"elements":[],"widgetType":"text-editor"},{"id":"d501041","elType":"widget","settings":{"text":"Learn More","link":{"url":"https://sedentist.com/about/","is_external":"","nofollow":"","custom_attributes":""},"align_mobile":"center","typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":15,"sizes":[]},"typography_font_weight":"500","typography_text_transform":"uppercase","button_text_color":"#BEBEBE","background_color":"#FFFFFF","hover_color":"#FFFFFF","button_background_hover_color":"#BEBEBE","border_border":"solid","border_width":{"unit":"px","top":"2","right":"2","bottom":"2","left":"2","isLinked":true},"border_color":"#BEBEBE","border_radius":{"unit":"px","top":"23","right":"23","bottom":"23","left":"23","isLinked":true},"text_padding":{"unit":"px","top":"13","right":"24","bottom":"13","left":"24","isLinked":false}}